// Probe: determine the wmma m16n16k16 accumulator fragment -> (row,col) mapping.
#include <mma.h>
#include <cuda_bf16.h>
#include <cstdio>
using namespace nvcuda;

__global__ void probe(float* out) {
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> f;
    for (int j = 0; j < 8; ++j) f.x[j] = (float)j;
    __shared__ float sm[16][16];
    wmma::store_matrix_sync(&sm[0][0], f, 16, wmma::mem_row_major);
    __syncthreads();
    for (int i = threadIdx.x; i < 256; i += 32) out[i] = sm[i / 16][i % 16];
}

int main() {
    float* d; cudaMalloc(&d, 256 * 4);
    probe<<<1, 32>>>();
    float h[256];
    cudaMemcpy(h, d, 256 * 4, cudaMemcpyDeviceToHost);
    cudaDeviceSynchronize();
    printf("j -> (row, col):\n");
    for (int j = 0; j < 8; ++j) {
        for (int r = 0; r < 16; ++r)
            for (int c = 0; c < 16; ++c)
                if (h[r * 16 + c] == (float)j) printf("  x%d -> (r=%2d, c=%2d)\n", j, r, c);
    }
    return 0;
}

