    cudaMemcpy(dk, hk.data(), BLOCK_N * HEAD_DIM * 2, cudaMemcpyHostToDevice);
    cudaMemcpy(dv, hv.data(), BLOCK_N * HEAD_DIM * 2, cudaMemcpyHostToDevice);
    cudaFuncSetAttribute(pipeline_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
    pipeline_kernel<<<1, NUM_THREADS, SMEM_BYTES>>>(dq, dk, dv, dp, do_, S, 1.f / sqrtf((float)HEAD_DIM));
