    cudaMemcpy(hp.data(), dp, S * S * 4, cudaMemcpyDeviceToHost);
    cudaMemcpy(ho.data(), do_, S * HEAD_DIM * 4, cudaMemcpyDeviceToHost);

    // host reference
    const float scale = 1.f / sqrtf((float)HEAD_DIM);
    std::vector<float> sref(S * S);
    for (int r = 0; r < S; ++r)
