            float a = 0.f;
            for (int d = 0; d < HEAD_DIM; ++d) a += (float)hq[r * HEAD_DIM + d] * (float)hk[c * HEAD_DIM + d];
            sref[r * S + c] = a * scale;
        }
    float pmax = 0.f; int pbad = 0;
    for (int i = 0; i < S * S; ++i) {
        float err = fabsf(hp[i] - __expf(sref[i] - sref[(i / S) * S + 0])); // not exact; use softmax below
    }
    std::vector<float> pref(S * S);
    for (int r = 0; r < S; ++r) {
        float mx = -1e30f, sum = 0.f;
        for (int c = 0; c < S; ++c) mx = fmaxf(mx, sref[r * S + c]);
        for (int c = 0; c < S; ++c) { pref[r * S + c] = __expf(sref[r * S + c] - mx); sum += pref[r * S + c]; }
        for (int c = 0; c < S; ++c) pref[r * S + c] /= sum;
    }
    for (int i = 0; i < S * S; ++i) {
        float err = fabsf(hp[i] - pref[i]);
        pmax = fmaxf(pmax, err);
        if (err > 0.01f) pbad++;
    }
    printf("P maxerr=%.5f nbad=%d\n", pmax, pbad);
    float omax = 0.f; int obad = 0;
    for (int r = 0; r < S; ++r)
        for (int d = 0; d < HEAD_DIM; ++d) {
            float ref = 0.f;
            for (int c = 0; c < S; ++c) ref += pref[r * S + c] * (float)hv[c * HEAD_DIM + d];
            float err = fabsf(ho[r * HEAD_DIM + d] - ref);
            omax = fmaxf(omax, err);
            if (err > 0.01f) obad++;
        }
    printf("O maxerr=%.5f nbad=%d\n", omax, obad);
    if (obad < 5) { for (int d = 0; d < 8; ++d) printf("  o[0,%d]=%.4f ref=%.4f\n", d, ho[d], 0.f); }
    return 0;
}

